 "Klávesy ve 3D (lze změnit v Nastavení → Klávesové zkratky):": "Keys in 3D (can be changed in Settings → Keyboard shortcuts):",
 "klíč=hodnota": "key=value",
 "Klik na plochu plechu v modelu přidá bod. Dvě čísla = souřadnice v rovině plochy (u vodorovné plochy x, y), tři = bod v prostoru (promítne se na plochu).": "Clicking a sheet face in the model adds a point. Two numbers = coordinates in the face plane (x, y on a horizontal face), three = a point in space (projected onto the face).",
 "Klik na rovinnou plochu plechu ji vybere{0}; bez výběru = horní plocha základního plechu.": "Clicking a flat sheet face selects it{0}; nothing selected = top face of the base sheet.",
