 "Klikněte na bod, hranu, plochu nebo těleso. Druhá entita změří vzdálenost a úhel mezi nimi.": "Click a point, edge, face or body. A second entity measures the distance and angle between them.",
 "Klikněte na body nebo entity (2 výběry)": "Click points or entities (2 selections)",
