 "Ostatní (volné)": "Other (free-form)",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Jen se nezobrazí 3D model.": "The rest of the program keeps working: menus, help, settings, opening and saving files, the 2D sketch and drawings. Only the 3D model is not displayed.",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Model se místo 3D okna zobrazuje jako zjednodušený náhled: pohledy, přizpůsobení, přiblížení, otáčení, řez i výběr ploch, hran a vrcholů kliknutím fungují (náhled je pravoúhlý; gizmo přesunu, skici a pomocné roviny v modelu nezobrazuje). Pro automatizaci (headless Chrome, Playwright, Puppeteer): spusťte prohlížeč bez přepínače --disable-software-rasterizer a s --enable-unsafe-swiftshader (případně --use-angle=swiftshader) – WebGL pak běží softwarově přes SwiftShader a zobrazí se plné 3D okno.": "The rest of the program keeps working: menus, help, settings, opening and saving files, 2D sketch and drawings. Instead of the 3D window the model is shown as a simplified preview: views, fit, zoom, rotation, section and selecting faces, edges and vertices by click all work (the preview is orthographic; it does not show the move gizmo, sketches or datum planes in the model). For automation (headless Chrome, Playwright, Puppeteer): launch the browser without the --disable-software-rasterizer switch and with --enable-unsafe-swiftshader (or --use-angle=swiftshader) – WebGL then runs in software via SwiftShader and the full 3D window appears.",
