 "Plochy lze místo klikání vybrat ze seznamů výše; hodnotu potvrdíte až po výběru obou ploch.": "Instead of clicking, the faces can be picked from the lists above; the value is confirmed after both faces are chosen.",
 "Plochy lze místo klikání vybrat ze seznamů výše.": "Instead of clicking, the faces can be picked from the lists above.",
 "Plochy lze vybrat i ze seznamu v tomto panelu; hotovou vazbu upravíte v seznamu Vazby pod stromem komponent.": "Faces can also be picked from a list in this panel; an existing mate is edited in the Mates list below the component tree.",
