 "poloměr {0} je menší než polovina tětivy {1}": "radius {0} is smaller than half the chord {1}",
 "Poloměr / velikost": "Radius / size",
 "Poloměr = polovina vzdálenosti rovnoběžných bočních ploch; prostřední plocha se nahradí válcem tečným k oběma. Prostřední plochu lze vynechat, je-li mezi bočními plochami jediná. Obdélníková prostřední plocha kolmá na boční se zaoblí přesně, jiná přibližně.": "Radius = half the distance between the parallel side faces; the middle face is replaced by a cylinder tangent to both. The middle face can be omitted if there is only one between the side faces. A rectangular middle face perpendicular to the sides is rounded exactly, others approximately.",
 "poloměr = povrch, kde závit začíná: válec, nebo díra (jádro); hloubka jde do materiálu": "radius = the surface where the thread starts: the cylinder, or the hole (minor diameter); the depth goes into the material",
