 "Profil": "Profile",
 "profil (kruh, závit 60° nebo skica) tažený po šroubovici – závit, pružina, spirálová drážka": "a profile (circle, 60° thread or sketch) swept along a helix – thread, spring, helical groove",
 "Profil (skica)": "Profile (sketch)",
 "Profil (uzavřená skica)": "Profile (closed sketch)",
 "Profil {0} {1} není v tabulce.": "Profile {0} {1} is not in the table.",
 "Profil {0} drážka {1} – L {2} mm": "Profile {0} slot {1} – L {2} mm",
 "Profil {0} L{1}": "Profile {0} L{1}",
 "Profil a dráha musí být dvě různé skici.": "The profile and the path must be two different sketches.",
 "Profil by měl ležet v rovině kolmé na začátek dráhy (kružnice bez skici se tam umístí sama). Dráha může obsahovat úsečky, oblouky a lomené čáry – musí být souvislá. Pevná orientace = profil se po dráze jen posouvá (nenatáčí se). Vodicí křivka natáčí profil směrem k ní. Kroucení a měřítko se staví z řezů podél dráhy (hladké šablonování) – výsledek je u dlouhých drah mírně přibližný. Transformovaný přechod je určen pro hladké dráhy.": "The profile should lie in a plane perpendicular to the start of the path (a circle without a sketch is placed there automatically). The path can contain lines, arcs and polylines – it must be continuous. Fixed orientation = the profile only translates along the path (does not rotate). A guide curve turns the profile towards it. Twist and scale are built from sections along the path (smooth loft) – for long paths the result is slightly approximate. The transformed transition is meant for smooth paths.",
 "Profil je po ořezání spojů záporný – zvolte menší profil nebo jiný typ spoje.": "The profile is negative after trimming the joints – choose a smaller profile or another joint type.",
 "Profil je prázdný.": "The profile is empty.",
 "Profil má nulovou délku.": "The profile has zero length.",
 "Profil má po zkrácení nulovou délku.": "The profile has zero length after shortening.",
 "profil po dráze": "profile along a path",
 "Profil řemene": "Belt profile",
 "Profil skici „{0}“: {1}.": "Profile of sketch “{0}”: {1}.",
 "Profil skici „{0}“: žádný uzavřený obrys.": "Profile of sketch “{0}”: no closed contour.",
 "Profil skici plochu neprotíná.": "The sketch profile does not intersect the surface.",
 "Profil U (UPN)": "U channel (UPN)",
 "Profil UPN {0} není v tabulce.": "Profile UPN {0} is not in the table.",
 "Profil;Ks;Délka celkem [m];Hmotnost [kg]": "Profile;Qty;Total length [m];Mass [kg]",
 "profil: {0} · ⚠ problémů {1}:": "profile: {0} · ⚠ {1} problems:",
 "profil: {0} ✓": "profile: {0} ✓",
 "profil: žádný uzavřený obrys": "profile: no closed contour",
 "profil: žádný uzavřený obrys – otevřená křivka {0} (konce {1} a {2}); k vysunutí ji uzavřete, jako dráha nebo dělicí čára je v pořádku": "profile: no closed contour – open curve {0} (ends {1} and {2}); close it to extrude, as a path or parting line it is fine",
 "Profilová kolejnice lineárního vedení HGR": "Linear guide rail HGR",
 "profily (2 a více skic)": "profiles (2 or more sketches)",
 "profily (jäkl, trubka, L, U, IPE…) podél úseček skici, rohy pokos/tupý": "profiles (hollow section, tube, L, U, IPE…) along sketch lines, corners mitred/butt",
 "Profily (v pořadí)": "Profiles (in order)",
 "Profily jsou uzavřené skici v různých rovinách (otvory se šablonují, mají-li všechny profily stejný počet). Stačí i jeden profil a bod (kužel / jehlan). Uzavřené šablonování potřebuje alespoň tři profily. Okrajové podmínky „kolmo“ / „směr“ jsou aproximace pomocným řezem v délce náběhu. Osová křivka má procházet profily (řezy se podél ní prokládají); vodicí křivka natáčí řezy směrem k sobě (použije se první). Osovou / vodicí křivku nelze kombinovat s bodem ani uzavřením.": "Profiles are closed sketches in different planes (holes are lofted when all profiles have the same number). One profile and a point is enough (cone / pyramid). A closed loft needs at least three profiles. The “normal” / “direction” boundary conditions are approximated by an auxiliary section at the lead-in length. The centreline should pass through the profiles (sections are interpolated along it); a guide curve turns the sections towards itself (the first one is used). A centreline / guide curve cannot be combined with a point or closing.",
 "Program": "Program",
 "Prohlížeč čtení schránky nedovoluje – vložte text do pole klávesami Ctrl+V.": "The browser does not allow reading the clipboard – paste the text into the field with Ctrl+V.",
 "Prohlížeč nedovolil číst schránku – vložte text do pole (Ctrl+V) a stiskněte Provést.": "The browser did not allow reading the clipboard – paste the text into the field (Ctrl+V) and press Run.",
 "Prohlížeč nepodporuje kreslení do canvasu.": "The browser does not support drawing into a canvas.",
 "prohlížeč neposkytl WebGL kontext (grafická akcelerace je vypnutá nebo nedostupná)": "the browser did not provide a WebGL context (graphics acceleration is disabled or unavailable)",
 "Prohlížeč neposkytl WebGL, tedy hardwarově akcelerovanou grafiku, kterou 3D zobrazení potřebuje ({0}). Nejčastější příčiny: vypnutá grafická akcelerace v prohlížeči, vzdálená plocha nebo virtuální stroj bez grafické karty, zastaralý ovladač grafiky, firemní zásady prohlížeče.{1}": "The browser did not provide WebGL, i.e. the hardware-accelerated graphics the 3D view needs ({0}). The most common causes: graphics acceleration disabled in the browser, a remote desktop or virtual machine without a graphics card, an outdated graphics driver, corporate browser policies.{1}",
 "Prohlížeč neumí kreslit do plátna (canvas) – podklad nelze vložit.": "The browser cannot draw to a canvas – the underlay cannot be inserted.",
 "Prohlížeč neumí nahrát video z 3D okna – použijte snímky PNG.": "The browser cannot record video from the 3D view – use PNG frames.",
