 "Průřez d2": "Cross-section d2",
 "Průřez je oblouk elipsy (nebo kuželosečky s parametrem rho) tečný k oběma plochám: D1 se odměří na první ploše, D2 na druhé. První plocha = plocha z pole výše, jinak plocha s normálou nejvíc nahoru (+Z, pak +Y, +X). Přímá hrana mezi rovinnými plochami a kruhová hrana se stálým průřezem (rovina ⟂ osa, souosý válec/kužel) jsou přesné; jiné hrany se proloží šablonováním průřezů (přibližně, ⚠). Vnitřní hrany materiál přidají.": "The section is an arc of an ellipse (or a conic with parameter rho) tangent to both faces: D1 is measured on the first face, D2 on the second. First face = the face from the field above, otherwise the face whose normal points most upwards (+Z, then +Y, +X). A straight edge between planar faces and a circular edge with a constant section (plane ⟂ axis, coaxial cylinder/cone) are exact; other edges are lofted through sections (approximate, ⚠). Concave edges add material.",
 "Průřez svarového kovu ≈ {0} mm² (t = {1} mm) · {2} kg/m": "Weld metal cross-section ≈ {0} mm² (t = {1} mm) · {2} kg/m",
