 "Úkos {0}° je pro tento profil příliš velký – obrys by se ve výšce {1} mm od roviny skici odsadil o {2} mm a zanikl. Zmenšete úhel nebo výšku.": "A {0}° draft is too large for this profile – at a height of {1} mm from the sketch plane the outline would be offset by {2} mm and vanish. Reduce the angle or the height.",
