 "Úprava (ISO 9692-1)": "Preparation (ISO 9692-1)",
 "Úprava {0} je pro tupý spoj dvou dílů – u vnitřního koutu použijte ½V, ½Y, K, J nebo 2J, nebo vyberte čelo dílu.": "Preparation {0} is for a butt joint of two parts – for an inner corner use ½V, ½Y, K, J or 2J, or select the end face of a part.",
 "Úprava {0} potřebuje poloměr dna R > 0.": "Preparation {0} needs a root radius R > 0.",
 "úprava a mazání kót a značek podle id z výkres stav (a1, a2…) nebo popisku; smazané vygenerované kóty se při přegenerování nevrátí": "edit and delete dimensions and marks by the id from drawing status (a1, a2…) or by label; deleted generated dimensions do not come back on regeneration",
 "Úprava bloku „{0}“": "Editing block “{0}”",
 "úprava definice bloku: přepne do prostoru bloku (kreslí se a upravuje obsah bloku, počátek = bod vložení); neexistující název založí nový blok; konec ZAVŘÍT-BLOK [Uložit/Zahodit]": "edit a block definition: switches to the block space (you draw and modify the block contents, origin = insertion point); a name that does not exist creates a new block; finish with BCLOSE [Save/Discard]",
 "Úprava dílu": "Editing part",
 "úprava I, V, Y, X, U, ½V, K, J (ISO 9692-1) vyříznutá do dílů + svarový kov jako těleso; tupý, T i rohový spoj": "I, V, Y, X, U, ½V, K, J preparation (ISO 9692-1) cut into the parts + weld metal as a body; butt, T and corner joints",
 "úprava křivky: úsečku / oblouk převede na křivku; Uzavřít / Otevřít, Spojit (navazující objekty), Šířka, Proložit (oblouky přes vrcholy), Spline (rám zůstane – Vyrovnat ho vrátí), Vyrovnat (zruší oblouky i proložení), Obrátit, Vložit / Odebrat vrchol, Více křivek, Zpět": "polyline editing: converts a line / arc to a polyline; Close / Open, Join (connected objects), Width, Fit (arcs through the vertices), Spline (the frame is kept – Decurve restores it), Decurve (removes arcs and fitting), Reverse, Insert / Remove vertex, Multiple polylines, Undo",
 "Úprava podsestavy": "Editing sub-assembly",
 "Úprava se vyřízne do spojovaných dílů (souměrné V, Y, X, U, 2U do obou, ½V, ½Y, K, J, 2J jen do vybraného), svarový kov s převýšením je těleso „Svar k“, podložka „Podložka k“. Náhled kreslí průřez pro zadanou tloušťku (0 = 10 mm, skutečná se změří v modelu).": "The preparation is cut into the joined parts (symmetric V, Y, X, U, 2U into both, ½V, ½Y, K, J, 2J only into the selected one); the weld metal with reinforcement is body “Svar k”, the backing strip “Podložka k”. The preview draws the cross-section for the given thickness (0 = 10 mm, the actual one is measured in the model).",
 "úprava skici: souřadnice / rozměry / pomocná entity (cx, cy, r, průměr, a=x;y, b=…, w, h, úhel, pomocná=ano), smazání entit (i s jejich vazbami a kótami), vazeb v1… a kót k1… (čísla vypíše stav), hodnota kóty a řídicí ↔ referenční; po řádku se skica vyřeší": "sketch editing: coordinates / sizes / construction flag of an entity (cx, cy, r, diameter, a=x;y, b=…, w, h, angle, construction=yes), deleting entities (with their constraints and dimensions), constraints v1… and dimensions k1… (numbers listed by status), dimension value and driving ↔ reference; the sketch is solved after the line",
 "úprava splajnu: Uzavřít / Otevřít, Spojit (navazující úsečky, oblouky, splajny), Posunout-bod (bod proložení nebo řídicí bod), Zjemnit (vložit uzel), Zvýšit-stupeň, Křivka (převod na křivku s přesností), Obrátit, Zpět": "spline editing: Close / Open, Join (connected lines, arcs, splines), Move point (fit point or control point), Refine (insert knot), Elevate order, Polyline (convert to polyline with precision), Reverse, Undo",
 "úprava úchopem (jako klik na modrý úchop vybrané entity): protáhnout úchop, posun, otočit, měřítko, zrcadlit kolem úchopu; Enter / mezera = další režim, Kopie = více kopií, Základní bod, Zpět": "grip editing (like clicking the blue grip of a selected entity): stretch the grip, move, rotate, scale, mirror about the grip; Enter / space = next mode, Copy = multiple copies, Base point, Undo",
 "úprava v kontextu je dostupná jen v aplikaci": "editing in context is only available in the application",
 "upraví obsah textu, odstavcového textu, kóty (<> = naměřená hodnota, prázdné = výchozí), odkazu, tolerance nebo značky; v GUI editor na místě": "edits the contents of a text, multiline text, dimension (<> = measured value, empty = default), leader, tolerance or symbol; in-place editor in the GUI",
 "upraví šrafu: Vzor, Měřítko, Úhel, Plná, Uživatelský, Dvojitá, Přechod, Ostrovy, Počátek; Hranice = obnovit smyčky z asociativních objektů; Načíst = vzory ze souboru .pat (text v uvozovkách)": "edits a hatch: Pattern, Scale, Angle, Solid, User, Double, Gradient, Islands, Origin; Boundary = recreate loops from associative objects; Load = patterns from a .pat file (text in quotes)",
