 "Uzavření": "Closure",
 "uzavření lomené čáry (i se zaoblenými rohy): „uzavřít“ / „otevřená“ platí vždy, první bod = poslední → uzavřená; jinak rozhodne skica – tvoří-li čára s dalšími entitami uzavřený obrys (oba konce propojené přes jiné entity), je otevřená, jinak se uzavře a protokol to ohlásí (ne, kdyby ji uzavírací úsek křížil); vznikne-li obrys později, čára se otevře; jako dráha (tažení, žebro, dělicí čára, pole podél křivky) se automatické uzavření nepoužije": "closing a polyline (also with rounded corners): “close” / “open” always win, first point = last → closed; otherwise the sketch decides – if the polyline forms a closed contour with other entities (both ends connected through other entities) it is open, otherwise it is closed and the log says so (not when the closing segment would cross it); if a contour forms later, the polyline opens; as a path (sweep, rib, parting line, pattern along a curve) automatic closing is not used",
