 "Ve směru vysunutí za rovinou skici není těleso – nástroj míří od tělesa (zkuste Opačný směr / „obráceně“).": "There is no body beyond the sketch plane in the extrusion direction – the tool points away from the body (try Reverse direction / “reverse”).",
 "Ve stavovém řádku přepněte filtr výběru na Plocha a klikněte v náhledu na rovinnou plochu komponenty – rovina řezu se na ni položí. Obecnou rovinu zadáte na záložce Vektor (normála).": "In the status bar set the selection filter to Face and click a planar face of a component in the preview – the section plane is placed on it. A general plane is entered on the Vector tab (normal).",
 "Ve středu": "Midpoint",
 "Ve vrcholu [{0}] se musí stýkat právě 3 hrany (nalezeno {1}).": "Exactly 3 edges must meet at vertex [{0}] ({1} found).",
 "Ve vrcholu, kde se stýkají aspoň tři vybrané hrany, zaoblení skončí ve vzdálenosti setback od vrcholu a roh uzavře hladká N-stranná záplata, tečná (G1) k zaoblením i k plochám rohu. Setback musí být alespoň rovný poloměru (stejná hodnota ≈ běžný kulový roh). Přesně pro rohy z rovinných ploch a přímých hran; jiné rohy dostanou běžné zaoblení vrcholu a prvek zobrazí ⚠.": "At a vertex where at least three selected edges meet, the fillets stop at the setback distance from the vertex and a smooth N-sided patch closes the corner, tangent (G1) to the fillets and to the corner faces. The setback must be at least the radius (equal value ≈ the usual spherical corner). Exact for corners of planar faces and straight edges; other corners get the regular vertex blend and the feature shows ⚠.",
