 "výběr entit textem stejně jako klik do modelu (i v náhledu bez WebGL): čísla jako popisky pro výběr a měřit; přidat = Ctrl + klik; nic = Esc; bez id vypíše výběr; v sestavě se stejnými komponentami #2:F3. Výběr převezmou tlačítka Zaoblit / Sražení / Skica na pásu karet a „+ aktuální výběr“ ve formulářích – textové příkazy ne: zaoblit 3 bez hran zaoblí všechny hrany, vybrané zadejte čísly (zaoblit 3 hrany E2;E5, skica plocha F3); také window.mncad.select()": "select entities by text just like a click into the model (also in the preview without WebGL): numbers as in the selection labels and measure; add = Ctrl + click; none = Esc; without an id it lists the selection; in an assembly with identical components #2:F3. The Fillet / Chamfer / Sketch ribbon buttons and “+ current selection” in forms take the selection over – text commands do not: fillet 3 without edges fillets all edges, give the selected ones by number (fillet 3 edges E2;E5, sketch face F3); also window.mncad.select()",
