 "Závit potřebuje těleso (válcovou plochu nebo díru).": "A thread needs a body (a cylindrical face or a hole).",
 "Závit potřebuje těleso (válcovou plochu).": "A thread needs a body (a cylindrical face).",
 "Závit se vymodeluje jako drážky (zjednodušeně, bez stoupání) – vhodné pro vizualizaci a 3D tisk. Skutečnou šroubovici dává Plochy → Tažení po šroubovici (profil Závit 60°).": "The thread is modelled as grooves (simplified, without pitch) – suitable for visualisation and 3D printing. A real helix is made with Surfaces → Helix sweep (Thread 60° profile).",
 "Závit zadní": "Rear thread",
