 "Závitová díra 2": "Threaded hole 2",
 "závitová díra: bez průměru = tabulkový vrták (M8 → 6,8, M18×1,5 → 16,5); zadaný průměr má přednost (protokol: vrták zadán ručně); jmenovitý průměr (díra 8 závit M8) = tabulkový vrták s poznámkou; „jádro“ (EN core, DE Kern) = malý průměr D1 podle ISO 965-1 (M8 → 6,647); „vrták N“ (EN drill N, DE Bohrer N) = vlastní vrták. Dno slepé díry: „dno ploché“ (EN flat bottom, DE flacher Grund) – sedlo pružiny, frézované dno – nebo „hrot 118|120|90“ (EN tip, DE Spitze; 60–170°, „hrot 180“ = ploché; také „ploché“, „bez hrotu“, „dno kužel 120“); platí i pro závitovou a zahloubenou díru; volby díry pište před „název“": "tapped hole: without a diameter = table tap drill (M8 → 6.8, M18×1.5 → 16.5); an entered diameter takes precedence (log: drill entered manually); the nominal diameter (hole 8 thread M8) = table tap drill with a note; “core” (CZ jádro, DE Kern) = minor diameter D1 per ISO 965-1 (M8 → 6.647); “drill N” (CZ vrták N, DE Bohrer N) = custom drill. Blind-hole bottom: “flat bottom” (CZ dno ploché, DE flacher Grund) – spring seat, milled bottom – or “tip 118|120|90” (CZ hrot, DE Spitze; 60–170°, “tip 180” = flat; also “flat”, “without tip”, “bottom cone 120”); also applies to tapped and counterbored holes; write the hole options before “name”",
